selector_to_html = {"a[href=\"#q-a\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Q&amp;A<a class=\"headerlink\" href=\"#q-a\" title=\"Link to this heading\">#</a></h1><h2>Q: After installation, running the program reports: version GLIBC or GLIBCXX not found<a class=\"headerlink\" href=\"#q-after-installation-running-the-program-reports-version-glibc-or-glibcxx-not-found\" title=\"Link to this heading\">#</a></h2><p>A: Check which GLIBC / GLIBCXX versions are supported by libc.so.6 and libstdc++.so.6.0.30 in your environment:</p>", "a[href=\"#testing-and-validation\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">3. Testing and validation<a class=\"headerlink\" href=\"#testing-and-validation\" title=\"Link to this heading\">#</a></h2><p>Refer to <a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagTree/blob/triton_v3.6.x/.github/workflows/hopper-build-and-test.yml\">Tests of nvidia backend</a></p>", "a[href=\"#manually-download-the-llvm\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">1.2 Manually download the LLVM<a class=\"headerlink\" href=\"#manually-download-the-llvm\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#use-the-image-for-triton-3-6\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">1.1 Use the image (for Triton 3.6)<a class=\"headerlink\" href=\"#use-the-image-for-triton-3-6\" title=\"Link to this heading\">#</a></h3><p>If your network connection is available, you do not need to perform the later step 1.x, because dependencies will be fetched automatically during the build.</p>", "a[href=\"#manually-download-the-triton-dependencies\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">1.3 Manually download the Triton dependencies<a class=\"headerlink\" href=\"#manually-download-the-triton-dependencies\" title=\"Link to this heading\">#</a></h3><p>The Triton dependencies are already downloaded and installed in the image.\nIf you do not need to build FlagTree or Triton from source, you do not need to download the Triton dependencies.</p>", "a[href=\"#build-from-source\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">2.2 Build from Source<a class=\"headerlink\" href=\"#build-from-source\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#q-after-installation-running-the-program-reports-version-glibc-or-glibcxx-not-found\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Q: After installation, running the program reports: version GLIBC or GLIBCXX not found<a class=\"headerlink\" href=\"#q-after-installation-running-the-program-reports-version-glibc-or-glibcxx-not-found\" title=\"Link to this heading\">#</a></h2><p>A: Check which GLIBC / GLIBCXX versions are supported by libc.so.6 and libstdc++.so.6.0.30 in your environment:</p>", "a[href=\"#nvidia-amd-nvidia-amd\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\ud83d\udcab NVIDIA &amp; AMD <a class=\"reference internal\" href=\"#/third_party/nvidia/\"><span class=\"xref myst\">nvidia</span></a> &amp; <a class=\"reference internal\" href=\"#/third_party/amd/\"><span class=\"xref myst\">amd</span></a><a class=\"headerlink\" href=\"#nvidia-amd-nvidia-amd\" title=\"Link to this heading\">#</a></h1><h2>1. Environment for build and run<a class=\"headerlink\" href=\"#environment-for-build-and-run\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the image (for Triton 3.6)<a class=\"headerlink\" href=\"#use-the-image-for-triton-3-6\" title=\"Link to this heading\">#</a></h3><p>If your network connection is available, you do not need to perform the later step 1.x, because dependencies will be fetched automatically during the build.</p>", "a[href=\"#environment-for-build-and-run\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">1. Environment for build and run<a class=\"headerlink\" href=\"#environment-for-build-and-run\" title=\"Link to this heading\">#</a></h2><h3>1.1 Use the image (for Triton 3.6)<a class=\"headerlink\" href=\"#use-the-image-for-triton-3-6\" title=\"Link to this heading\">#</a></h3><p>If your network connection is available, you do not need to perform the later step 1.x, because dependencies will be fetched automatically during the build.</p>", "a[href=\"#installation-commands\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">2. Installation Commands<a class=\"headerlink\" href=\"#installation-commands\" title=\"Link to this heading\">#</a></h2><h3>2.1 Source-free Installation<a class=\"headerlink\" href=\"#source-free-installation\" title=\"Link to this heading\">#</a></h3><p>After installing <code class=\"docutils literal notranslate\"><span class=\"pre\">flagtree</span></code>, you can check it with:</p>", "a[href=\"#source-free-installation\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">2.1 Source-free Installation<a class=\"headerlink\" href=\"#source-free-installation\" title=\"Link to this heading\">#</a></h3><p>After installing <code class=\"docutils literal notranslate\"><span class=\"pre\">flagtree</span></code>, you can check it with:</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
